olor:#ff8993!important}.candidate{color:var(--candidate)}.table-panel{margin-top:12px}.scroll{max-height:260px;overflow:auto}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:6px 9px;border-bottom:1px solid #202e40;white-space:nowrap;text-align:right}th{position:sticky;top:0;background:#172336;color:#9caec4;font-size:11px}th:first-child,td:first-child{text-align:left}.up{color:var(--up)}.down{color:var(--down)}.empty{text-align:center!important;color:var(--muted);padding:22px}.section-no{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;padding:0 6px;border-radius:11px;background:#245b8a;color:#fff;font-weight:800;font-size:11px;margin-right:5px}.hide-section-numbers .section-no{display:none}.groupbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:8px 18px;background:#0d1622;border-bottom:1px solid var(--line)}.groupbar select{max-width:180px}.groupbar .navpair{display:flex;gap:4px}.groupbar button{margin-left:0}.modal{position:fixed;inset:0;z-index:20;background:rgba(0,0,0,.65);display:none;align-items:center;justify-content:center;padding:16px}.modal.open{display:flex}.modal-card{width:min(620px,100%);max-height:85vh;overflow:auto;background:#121c2a;border:1px solid #35506f;border-radius:10px;padding:16px}.member-row{display:flex;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #27364b}.member-row span{flex:1}.group-row{display:flex;align-items:center;gap:6px}.group-row label{display:flex;align-items:center;gap:4px}.group-row select{min-width:150px}.sim-panel{margin-top:10px;padding:9px 11px}.sim-controls{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.sim-controls input[type=number]{width:82px}.sim-controls button{margin-left:0}.sim-hint{color:var(--candidate);font-size:12px}.sim-result{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:1px;margin-top:9px;background:var(--line);border:1px solid var(--line)}.sim-result>div{padding:7px 9px;background:#0e1825;min-height:51px}.sim-result span{display:block;color:var(--muted);font-size:10px}.sim-result strong{display:block;font-size:13px;font-variant-numeric:tabular-nums}.sim-result .sim-wide{grid-column:span 2}.sim-empty{grid-column:1/-1!important;color:var(--muted);min-height:auto!important}.sim-positive{color:var(--up)}.sim-negative{color:var(--down)}.chart-panel #simChart{position:absolute;inset:0;pointer-events:none}
.auto-switches{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding-left:4px;border-left:1px solid var(--line)}.auto-note{color:var(--muted);font-size:11px}.auto-table td:first-child,.auto-table th:first-child{text-align:left}.strategy-a{color:#73b7ff}.strategy-b{color:#d9a7ff}
.annotation-panel{margin-top:10px;padding:10px 11px}.annotation-controls{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.annotation-controls textarea{flex:1 1 260px;min-height:38px;resize:vertical;border:1px solid var(--line);border-radius:4px;background:#0b1420;color:var(--text);padding:7px}.annotation-target{color:var(--candidate);min-width:185px}.annotation-list{margin-top:9px;max-height:220px;overflow:auto}.annotation-list td:nth-child(3){white-space:normal;text-align:left;min-width:180px}.annotation-list button{margin:0 0 0 5px;padding:4px 7px}.annotation-good{color:#54d98c}.annotation-bad{color:#ff7180}.annotation-watch{color:#ffc857}.chart-panel #annotationChart{position:absolute;inset:0;pointer-events:none}
@media(max-width:700px){.groupbar{display:flex;flex-direction:column;align-items:stretch;gap:7px;padding:8px}.groupbar>.section-no{align-self:flex-start}.group-row{display:grid;grid-template-columns:82px minmax(0,1fr) 82px;gap:8px;width:100%;align-items:center}.group-row label{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:6px;min-width:0}.group-row select{width:100%;min-width:0;max-width:none;margin-left:0}.group-row button{width:100%;min-height:46px;font-size:16px;padding:8px 5px}.groupbar>#manageGroups{width:100%;min-height:42px}.groupbar .wide{grid-column:auto}.groupbar select{max-width:none;width:100%}.groupbar .wide{grid-column:1/-1}.groupbar select{max-width:none;width:100%}.groupbar button{min-height:40px}.controls{gap:7px}.controls label{font-size:12px}.sim-controls{align-items:stretch}.sim-controls label{display:flex;align-items:center;justify-content:space-between;flex:1 1 145px}.sim-controls input[type=number],.sim-controls select{width:80px}.sim-result{grid-template-columns:repeat(2,minmax(0,1fr))}.sim-result .sim-wide{grid-column:span 2}.auto-switches{width:100%;border-left:0;border-top:1px solid var(--line);padding:8px 0 0}.auto-switches label{flex:1 1 145px}.annotation-controls{align-items:stretch}.annotation-controls>*{flex:1 1 100%;margin-left:0}.annotation-controls button{min-height:40px}}@media(max-width:1000px){header{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:repeat(3,1fr)}.chart-panel{height:400px}.sim-result{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.sim-result{grid-template-columns:repeat(2,minmax(0,1fr))}.sim-result .sim-wide{grid-column:span 2}}
</style>
</head>
<body>
<header>
  <div style="display:flex;gap:10px;align-items:center"><h1>A18_2 · K線波段轉折觀察</h1><span class="tag">LIVE / HISTORY</span></div>
  <form id="controls" class="controls"><span class="section-no">1</span>
    <label>股票 <input id="symbol" value="2330" maxlength="12"></label>
    <button type="button" id="prevDay">← 上一日</button>
    <label>日期 <input id="date" type="date"> <strong id="weekday" style="color:var(--text)">—</strong></label>
    <button type="button" id="nextDay">下一日 →</button>
    <label>K線 <select id="interval"><option value="1">1秒</option><option value="5" selected>5秒</option><option value="60">1分</option><option value="300">5分</option></select></label>
    <label>反轉 <select id="threshold"><option value="0.003">0.3%</option><option value="0.005">0.5%</option><option value="0.008">0.8%</option><option value="0.01" selected>1.0%</option><option value="0.015">1.5%</option><option value="0.02">2.0%</option></select></label>
    <label class="switch" title="以當日開盤為 0%，將加權指數 IX0001 疊加在主圖"><input id="overlay" type="checkbox"><span class="slider"></span><span>加權指數</span></label>
    <label class="switch" title="將目前日期之前的 N 個交易日一起接續畫在 K 線圖"><input id="multiDay" type="checkbox"><span class="slider"></span><span>多日</span></label>
    <label id="lookbackWrap">往前 <input id="lookbackDays" type="number" min="1" max="20" value="1" style="width:58px"> 個交易日</label>
    <button type="submit">載入 / 更新</button>
    <label><input id="auto" type="checkbox" checked> 5秒自動更新</label>
    <label class="switch" title="顯示各功能區塊的數字編號"><input id="showSectionNumbers" type="checkbox" checked><span class="slider"></span><span>區塊編號</span></label>
  </form>
</header>
<main>
  <section class="summary"><span class="section-no">3</span>
    <div><span>股票</span><strong id="sSymbol">—</strong></div>
    <div><span>日期</span><strong id="sDate">—</strong></div>
    <div><span>最新價</span><strong id="sPrice">—</strong></div>
    <div><span>K棒數</span><strong id="sBars">—</strong></div>
    <div><span>已確認轉折</span><strong id="sTurns">—</strong></div>
    <div><span>候選轉折</span><strong id="sCandidate" class="candidate">—</strong></div>
    <div><span>資料狀態</span><strong id="sState">—</strong></div>
  </section>
<section class="groupbar"><span class="section-no">2</span>
  <div class="group-row group-row-main"><button type="button" id="prevGroup">← 群</button><label>群組 <select id="groupSelect"><option value="">未選群組</option></select></label><button type="button" id="nextGroup">群 →</button></div>
  <div class="group-row"><button type="button" id="prevMember">← 股</button><label>群內個股 <select id="memberSelect"><option value="">—</option></select></label><button type="button" id="nextMember">股 →</button></div>
  <button type="button" id="manageGroups">管理群組</button>
</section>
<div id="groupModal" class="modal"><div class="modal-card"><h2 style="margin-top:0">群組管理</h2><div style="display:flex;gap:8px"><input id="newGroupName" placeholder="新群組名稱" style="flex:1"><button type="button" id="addGroup">新增群組</button></div><hr style="border-color:#27364b"><label>編輯群組 <select id="editGroup"></select></label><button type="button" id="deleteGroup">刪除此群組</button><div style="display:flex;gap:8px;margin-top:12px"><input id="newMemberSymbol" placeholder="股票代號，例如 2330" style="flex:1"><button type="button" id="addMember">加入個股</button></div><div id="memberList" style="margin-top:10px"></div><div style="text-align:right;margin-top:14px"><button type="button" id="closeGroups">完成</button></div></div></div>
  <p id="status">準備載入。</p>
  <section class="panel sim-panel">
    <div class="sim-controls"><span class="section-no">4</span>
      <label class="switch" title="啟用後點擊 K 線選擇進場棒"><input id="simSelect" type="checkbox"><span class="slider"></span><span>選擇進場</span></label>
      <div class="auto-switches"><label class="switch" title="僅分析：5秒突跳達0.3%，再確認5秒延續達0.1%；不送實單"><input id="autoStrategyA" type="checkbox"><span class="slider"></span><span>策略A LONG</span></label><label>A停損% <input id="autoAStopPct" type="number" min="0" step="0.1" value="1" style="width:70px"></label><label>A移動% <input id="autoATrailPct" type="number" min="0" step="0.1" value="0.5" style="width:70px"></label><label class="switch" title="僅分析：09:00~10:00 高點60秒內回落0.3%、20根均量3倍且收低；不送實單"><input id="autoStrategyB" type="checkbox"><span class="slider"></span><span>策略B SHORT</span></label><label>B停損% <input id="autoBStopPct" type="number" min="0" step="0.1" value="0.7" style="width:70px"></label><label>B移動% <input id="autoBTrailPct" type="number" min="0" step="0.1" value="1" style="width:70px"></label><span class="auto-note">僅分析，不送實單</span></div>
      <label>方向 <select id="simDirection"><option value="LONG">LONG 多單</option><option value="SHORT">SHORT 空單</option></select></label>
      <label>股數 <input id="simQuantity" type="number" min="1" step="1" value="1000"></label>
      <label>稅別 <select id="simTaxMode"><option value="DAYTRADE">DAYTRADE 當沖</option><option value="NORMAL">NORMAL 一般</option></select></label>
      <label>手續費率 % <input id="simFeeRate" type="number" min="0" step="0.0001" value="0.0855"></label>
      <label>最低手續費 <input id="simMinFee" type="number" min="0" step="1" value="20"></label>
      <label>固定停損 % <input id="simStopPct" type="number" min="0" step="0.1" value="1"></label>
      <label>移動停利回落 % <input id="simTrailPct" type="number" min="0" step="0.1" value="1.5"></label>
      <button type="button" id="simClear">清除進場</button><span id="simHint" class="sim-hint">開啟「選擇進場」後點擊 K 線</span>
    </div>
    <div id="simResult" class="sim-result"><div class="sim-empty">尚未選擇進場 K 棒。</div></div>
  </section>
  <section class="panel annotation-panel">
    <div class="annotation-controls"><span class="section-no">5</span><label class="switch" title="啟用後點擊 K 線新增或編輯策略 A 人工標註"><input id="annotationMode" type="checkbox"><span class="slider"></span><span>策略 A 標註模式</span></label><span id="annotationTarget" class="annotation-target">開啟後點擊 K 線</span><label>標籤 <select id="annotationLabel"><option>A進場好點</option><option>A進場不要</option><option>觀察但沒進</option></select></label><textarea id="annotationNote" maxlength="4000" placeholder="備註（可留空）"></textarea><button type="button" id="annotationSave" disabled>儲存標註</button><button type="button" id="annotationCancel">取消編輯</button></div>
    <div class="annotation-list"><table><thead><tr><th>時間</th><th>標籤</th><th>備註</th><th>操作</th></tr></thead><tbody id="annotationRows"><tr><td colspan="4" class="empty">尚無標註</td></tr></tbody></table></div>
  </section>
  <section class="panel chart-panel"><span class="section-no" style="position:absolute;z-index:3;left:6px;top:6px">6</span><canvas id="chart"></canvas><canvas id="annotationChart"></canvas><canvas id="simChart"></canvas><canvas id="hoverChart"></canvas></section>
  <div id="chartTooltip" class="chart-tooltip"></div>
  <section class="panel table-panel auto-table"><div style="padding:7px 9px 0"><span class="section-no">7</span><span style="color:var(--muted)">自動策略交易清單（僅分析）</span></div><div class="scroll"><table><thead><tr><th>策略</th><th>方向</th><th>進場時間</th><th>進場價</th><th>出場時間</th><th>出場價</th><th>出場原因</th><th>淨損益</th><th>實際報酬率</th></tr></thead><tbody id="autoTrades"><tr><td colspan="9" class="empty">策略 A / B 預設關閉</td></tr></tbody></table></div></section>
  <section class="panel table-panel"><div style="padding:7px 9px 0"><span class="section-no">8</span><span style="color:var(--muted)">波段列表</span></div><div class="scroll"><table><thead><tr><th>波段</th><th>起訖時間</th><th>起訖價</th><th>方向</th><th>漲跌幅</th><th>Retracement</th></tr></thead><tbody id="segments"><tr><td colspan="6" class="empty">尚無波段</td></tr></tbody></table></div></section>
</main>
<script>
(()=>{'use strict';const $=id=>document.getElementById(id);const state={bars:[],indexBars:[],turns:[],candidate:null,timer:null,hoverIndex:null,geometry:null,dayRanges:[],simEntryTime:null,simulation:null,autoTrades:[],annotations:[],annotationBar:null,annotationId:null};
const fmtP=n=>Number(n).toLocaleString('zh-TW',{maximumFractionDigits:4});const fmtT=s=>new Date(s).toLocaleTimeString('zh-TW',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});
const fmtMoney=n=>Math.trunc(Number(n)).toLocaleString('zh-TW');
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function annotationMeta(label){return label==='A進場好點'?{cls:'annotation-good',color:'#54d98c',code:'A✓'}:label==='A進場不要'?{cls:'annotation-bad',color:'#ff7180',code:'A×'}:{cls:'annotation-watch',color:'#ffc857',code:'A?'}}
function annotationBarIndex(time){if(!state.bars.length)return-1;const target=new Date(time).getTime();let best=-1,dist=Infinity;for(let i=0;i<state.bars.length;i++){const d=Math.abs(new Date(state.bars[i].startTime).getTime()-target);if(d<dist){dist=d;best=i}}return dist<=Math.max(1000,(+$('interval').value||1)*1000)?best:-1}
function resetAnnotationEditor(){state.annotationBar=null;state.annotationId=null;$('annotationNote').value='';$('annotationLabel').value='A進場好點';$('annotationSave').disabled=true;$('annotationTarget').textContent=$('annotationMode').checked?'請點擊 K 線選擇標註位置':'開啟後點擊 K 線'}
function renderAnnotations(){const body=$('annotationRows'),rows=state.annotations||[];body.innerHTML=rows.length?rows.map(a=>{const m=annotationMeta(a.label);return `<tr><td>${fmtT(a.barTime)}<br><span style="color:var(--muted)">${fmtP(a.price)}</span></td><td class="${m.cls}">${esc(a.label)}</td><td>${esc(a.note||'')}</td><td><button type="button" data-ann-edit="${a.id}">編輯</button><button type="button" data-ann-delete="${a.id}">刪除</button></td></tr>`}).join(''):'<tr><td colspan="4" class="empty">尚無標註</td></tr>'}
async function refreshAnnotations(){const symbol=$('symbol').value.trim().toUpperCase(),date=$('date').value;if(!symbol||!date){state.annotations=[];renderAnnotations();drawAnnotationMarkers();return}try{const r=await fetch(`/api/swing/annotations?symbol=${encodeURIComponent(symbol)}&date=${encodeURIComponent(date)}`,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);state.annotations=await r.json();renderAnnotations();drawAnnotationMarkers()}catch(e){state.annotations=[];renderAnnotations();$('status').textContent=`標註載入失敗：${e.message}`;$('status').className='error'}}
function chooseAnnotationBar(i){const b=state.bars[i];if(!b)return;const existing=(state.annotations||[]).find(a=>new Date(a.barTime).getTime()===new Date(b.startTime).getTime());state.annotationBar=b;state.annotationId=existing?.id||null;$('annotationLabel').value=existing?.label||'A進場好點';$('annotationNote').value=existing?.note||'';$('annotationSave').disabled=false;$('annotationTarget').textContent=`${existing?'編輯':'新增'} ${String(b.startTime).slice(0,10)} ${fmtT(b.startTime)} @ ${fmtP(b.close)}`}
async function saveAnnotation(){const b=state.annotationBar;if(!b)return;const payload={symbol:$('symbol').value.trim().toUpperCase(),tradeDate:String(b.startTime).slice(0,10),barTime:b.startTime,price:Number(b.close),label:$('annotationLabel').value,note:$('annotationNote').value};const url=state.annotationId?`/api/swing/annotations/${state.annotationId}`:'/api/swing/annotations',method=state.annotationId?'PUT':'POST';const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){let msg=`HTTP ${r.status}`;try{msg=(await r.json()).error||msg}catch{}throw new Error(msg)}resetAnnotationEditor();await refreshAnnotations()}
async function deleteAnnotation(id){if(!confirm('刪除此人工標註？'))return;const r=await fetch(`/api/swing/annotations/${id}`,{method:'DELETE'});if(!r.ok&&r.status!==404)throw new Error(`刪除失敗 HTTP ${r.status}`);if(state.annotationId===id)resetAnnotationEditor();await refreshAnnotations()}
function drawAnnotationMarkers(){const cv=$('annotationChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const g=state.geometry;if(!g)return;c.save();for(const a of state.annotations||[]){const i=annotationBarIndex(a.barTime);if(i<0)continue;const x=g.p.l+(i+.5)*g.cw,y=g.y(Number(a.price)),m=annotationMeta(a.label);c.fillStyle=m.color;c.strokeStyle='#08111d';c.lineWidth=2;c.beginPath();c.moveTo(x,y-9);c.lineTo(x+8,y+5);c.lineTo(x-8,y+5);c.closePath();c.fill();c.stroke();c.font='bold 11px system-ui';c.fillStyle=m.color;c.fillText(`${m.code} ${fmtP(a.price)}`,Math.min(g.w-95,x+9),Math.max(g.p.t+12,y-9))}c.restore()}
function simParams(){return{direction:$('simDirection').value,quantity:Math.max(1,Math.trunc(+$('simQuantity').value||1)),taxMode:$('simTaxMode').value,feeRate:Math.max(0,+$('simFeeRate').value||0)/100,minFee:Math.max(0,+$('simMinFee').value||0),stopPct:Math.max(0,+$('simStopPct').value||0)/100,trailPct:Math.max(0,+$('simTrailPct').value||0)/100}}
