function draw(){const cv=$('chart'),r=cv.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);const c=cv.getContext('2d');c.scale(dpr,dpr);const bars=state.bars,w=r.width,h=r.height,p={l:64,r:18,t:20,b:32};c.clearRect(0,0,w,h);if(!bars.length){c.fillStyle='#8191a8';c.fillText('此日期尚無 K 線資料',p.l,p.t+15);return}const lo=Math.min(...bars.map(b=>Number(b.low))),hi=Math.max(...bars.map(b=>Number(b.high))),rg=hi-lo||Math.max(1,hi*.001),min=lo-rg*.08,max=hi+rg*.08;const y=v=>p.t+(max-v)/(max-min)*(h-p.t-p.b);const cw=(w-p.l-p.r)/Math.max(1,bars.length);state.geometry={w,h,p,cw,y};c.font='11px system-ui';c.strokeStyle='#27364b';c.fillStyle='#8191a8';for(let i=0;i<=5;i++){const yy=p.t+i*(h-p.t-p.b)/5,v=max-i*(max-min)/5;c.beginPath();c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.fillText(fmtP(v),4,yy+4)}if(state.dayRanges.length>1){c.save();c.font='11px system-ui';state.dayRanges.forEach((dr,k)=>{if(k>0){const x=p.l+dr.from*cw;c.strokeStyle='#52657c';c.setLineDash([3,4]);c.beginPath();c.moveTo(x,p.t);c.lineTo(x,h-p.b);c.stroke();c.setLineDash([])}const cx=p.l+((dr.from+dr.to+1)/2)*cw;c.fillStyle='#8191a8';c.fillText(String(dr.date).slice(5),Math.max(p.l,cx-28),h-8)});c.restore()}bars.forEach((b,i)=>{const x=p.l+(i+.5)*cw,o=Number(b.open),cl=Number(b.close),hh=Number(b.high),ll=Number(b.low),up=cl>=o;c.strokeStyle=up?'#ff5f6d':'#36d6a0';c.fillStyle=c.strokeStyle;c.beginPath();c.moveTo(x,y(hh));c.lineTo(x,y(ll));c.stroke();const top=Math.min(y(o),y(cl)),bh=Math.max(1,Math.abs(y(o)-y(cl)));c.fillRect(x-Math.max(1,cw*.28),top,Math.max(2,cw*.56),bh)});if($('overlay').checked&&state.indexBars.length){const ib=state.indexBars.filter(b=>Number(b.close)>0);if(ib.length){const bases={};for(const b of ib){const d=String(b.startTime).slice(0,10);if(!bases[d])bases[d]=Number(b.close)}const pctOf=b=>(Number(b.close)/(bases[String(b.startTime).slice(0,10)]||Number(b.close))-1)*100;const pcts=ib.map(pctOf),plo=Math.min(...pcts