function drawHover(){const cv=$('hoverChart'),base=$('chart'),r=base.getBoundingClientRect(),dpr=devicePixelRatio||1;if(cv.width!==Math.max(1,r.width*dpr)||cv.height!==Math.max(1,r.height*dpr)){cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr)}const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,r.width,r.height);const g=state.geometry,i=state.hoverIndex;if(!g||!Number.isInteger(i)||!state.bars[i])return;const b=state.bars[i],x=g.p.l+(i+.5)*g.cw,yy=g.y(Number(b.close));c.strokeStyle='rgba(225,236,246,.78)';c.lineWidth=1;c.setLineDash([5,4]);c.beginPath();c.moveTo(x,g.p.t);c.lineTo(x,g.h-g.p.b);c.moveTo(g.p.l,yy);c.lineTo(g.w-g.p.r,yy);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.beginPath();c.arc(x,yy,3.5,0,Math.PI*2);c.fill()}
function recompute(payload){state.bars=payload.bars||[];const z=zigzag(state.bars,+$('threshold').value);state.turns=z.turns;state.candidate=z.candidate;$('sSymbol').textContent=payload.name?`${payload.symbol} ${payload.name}`:payload.symbol;$('sDate').textContent=payload.tradeDate;$('sPrice').textContent=state.bars.length?fmtP(state.bars.at(-1).close):'—';$('sBars').textContent=state.bars.length;$('sTurns').textContent=state.turns.length;$('sCandidate').textContent=state.candidate?`候選${state.candidate.type} ${fmtP(state.candidate.price)} @ ${fmtT(state.candidate.time)}`:'—';$('sState').textContent=payload.dataState||'—';renderTable();draw()}
const drawBase=draw;draw=()=>{drawBase();updateSimulation();updateAutoStrategies();drawSimulationMarkers();drawAnnotationMarkers()};
async function isKnownNonTrading(date){try{const r=await fetch(`/api/calendar/non-trading/${date}`,{cache:'no-store'});return r.ok&&(await r.json()).nonTrading}catch{return false}}
async function previousTradingDates(date,count){const out=[];let d=new Date(date+'T12:00:00');for(let guard=0;out.length<count&&guard<120;guard++){d.setDate(d.getDate()-1);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(d.getDay()===0||d.getDay()===6)continue;if(await isKnownNonTrading(v))continue;out.push(v)}return out.reverse()}
async function fetchBars(symbol,date,interval){const r=await fetch(`/api/bars/${encodeURIComponent(symbol)}?date=${encodeURIComponent(date)}&interval=${interval}`,{cache:'no-store'});const text=await r.text();let j={};try{j=text?JSON.parse(text):{}}catch{throw new Error(`HTTP ${r.status} 回傳非 JSON`)}if(!r.ok)throw new Error(j.error||`HTTP ${r.status}`);return j}
async function load(){const symbol=$('symbol').value.trim().toUpperCase(),date=$('date').value,interval=$('interval').value;if(!symbol||!date)return;$('status').textContent=`載入 ${symbol} ${date}…`;$('status').className='';try{let dates=[date];if($('multiDay').checked){const n=Math.max(1,Math.min(20,parseInt($('lookbackDays').value)||1));dates=[...(await previousTradingDates(date,n)),date]}const payloads=[];for(const d of dates){const j=await fetchBars(symbol,d,interval);if(j.dataState==='FUTURE_DATE'&&d===date){payloads.push(j);continue}if(!j.hasData&&d!==date){if(j.source==='SINOPAC_SHIOAJI_NO_DATA'||j.source==='KNOWN_NON_TRADING_DAY'){continue}}payloads.push(j)}const main=payloads.at(-1)||await fetchBars(symbol,date,interval);const combined=[];state.dayRanges=[];for(const j of payloads){if(!j.hasData)continue;const from=combined.length;combined.push(...(j.bars||[]));state.dayRanges.push({date:j.tradeDate,from,to:combined.length-1})}main.bars=combined;main.hasData=combined.length>0;main.dataState=combined.length?'AVAILABLE':main.dataState;if($('overlay').checked&&symbol!=='IX0001'){const idx=[];for(const d of dates){const j=await fetchBars('IX0001',d,interval);if(j.hasData)idx.push(...j.bars)}state.indexBars=idx}else state.indexBars=[];recompute(main);await refreshAnnotations();$('status').textContent=main.hasData?`已載入 ${main.bars.length} 根 K${state.dayRanges.length>1?`（${state.dayRanges.length} 個交易日）`:''}；資料來源：${main.source||'A18_2 LIVE'}。`:main.dataState==='FUTURE_DATE'?`${date} 尚未到達，不進行資料查詢。`:`${date} 目前尚無資料（NO_DATA_YET）。`}catch(e){state.bars=[];state.indexBars=[];state.turns=[];state.candidate=null;state.hoverIndex=null;state.dayRanges=[];state.annotations=[];renderAnnotations();resetAnnotationEditor();drawAnnotationMarkers();$('sDate').textContent=date;$('sPrice').textContent='—';$('sBars').textContent='0';$('sTurns').textContent='0';$('sCandidate').textContent='—';$('sState').textContent='ERROR';renderTable();draw();drawHover();$('status').textContent='載入失敗：'+e.message;$('status').className='error'}}
const chart=$('chart'),tip=$('chartTooltip');chart.addEventListener('mousemove',e=>{const g=state.geometry;if(!g||!state.bars.length)return;const r=chart.getBoundingClientRect(),mx=e.clientX-r.left;const raw=(mx-g.p.l)/Math.max(0.000001,g.cw)-.5;const i=Math.max(0,Math.min(state.bars.length-1,Math.round(raw)));state.hoverIndex=i;drawHover();const b=state.bars[i],up=Number(b.close)>=Number(b.open);let indexTip='';if($('overlay').checked&&state.indexBars.length){const bt=new Date(b.startTime).getTime();let ib=null,best=Infinity;for(const x of state.indexBars){const d=Math.abs(new Date(x.startTime).getTime()-bt);if(d<best){best=d;ib=x}}if(ib&&best<=Math.max(1000,+$('interval').value*1000)){const day=String(ib.startTime).slice(0,10),base=Number(state.indexBars.find(x=>String(x.startTime).slice(0,10)===day&&Number(x.close)>0)?.close||0),iv=Number(ib.close),pct=base>0?(iv/base-1)*100:null;indexTip=`\n────────────\nIX0001 ${fmtP(iv)}${pct==null?'':`   ${pct>=0?'+':''}${pct.toFixed(2)}%`}`}}tip.textContent=`${String(b.startTime).slice(0,10)} ${fmtT(b.startTime)}\nO ${fmtP(b.open)}   H ${fmtP(b.high)}\nL ${fmtP(b.low)}   C ${fmtP(b.close)}\nV ${Number(b.volume).toLocaleString('zh-TW')}   ticks ${b.tickCount}${indexTip}`;tip.style.display='block';tip.style.left=`${Math.min(innerWidth-230,e.clientX+14)}px`;tip.style.top=`${Math.min(innerHeight-125,e.clientY+14)}px`;tip.style.borderColor=up?'#8d4a53':'#2f7765'});chart.addEventListener('mouseleave',()=>{state.hoverIndex=null;tip.style.display='none';drawHover()});$('controls').addEventListener('submit',e=>{e.preventDefault();load()});$('threshold').addEventListener('change',()=>state.bars.length&&recompute({symbol:$('symbol').value.trim().toUpperCase(),tradeDate:$('date').value,dataState:'AVAILABLE',bars:state.bars}));$('interval').addEventListener('change',load);$('date').addEventListener('change',()=>{updateWeekday();savePrefs();load()});$('auto').addEventListener('change',()=>{clearInterval(state.timer);state.timer=$('auto').checked?setInterval(load,5000):null});window.addEventListener('resize',()=>{draw();drawHover()});
chart.addEventListener('click',e=>{if(!state.geometry||!state.bars.length)return;const r=chart.getBoundingClientRect(),raw=(e.clientX-r.left-state.geometry.p.l)/Math.max(.000001,state.geometry.cw)-.5,i=Math.max(0,Math.min(state.bars.length-1,Math.round(raw)));state.hoverIndex=i;if($('annotationMode').checked){chooseAnnotationBar(i);drawHover();return}if(!$('simSelect').checked)return;state.simEntryTime=state.bars[i].startTime;updateSimulation();drawSimulationMarkers();drawHover()});
$('simSelect').addEventListener('change',()=>{if($('simSelect').checked&&$('annotationMode').checked){$('annotationMode').checked=false;resetAnnotationEditor()}$('simHint').textContent=$('simSelect').checked?'請點擊 K 線選擇進場棒':state.simulation?`${state.simulation.direction}｜${state.simulation.open?'OPEN／未出場':'已出場'}｜從進場後下一根 K 棒開始模擬`:'開啟「選擇進場」後點擊 K 線';chart.style.cursor=$('simSelect').checked?'copy':'crosshair'});
