let swingGroups={},symbolNames={};
async function loadGroups(){try{const [r,n]=await Promise.all([fetch('/api/swing/groups',{cache:'no-store'}),fetch('/api/symbols/names',{cache:'no-store'})]);if(r.ok)swingGroups=await r.json();if(n.ok)symbolNames=await n.json()}catch{}renderGroupSelectors()}
async function saveGroups(){const r=await fetch('/api/swing/groups',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(swingGroups)});if(!r.ok)throw new Error('群組儲存失敗');swingGroups=await r.json();renderGroupSelectors();renderGroupEditor()}
function groupNames(){return Object.keys(swingGroups)}
function renderGroupSelectors(){const gs=$('groupSelect'),keep=gs.value||prefs?.group||'';gs.innerHTML='<option value="">未選群組</option>'+groupNames().map(x=>`<option value="${x.replaceAll('&','&amp;').replaceAll('"','&quot;')}">${x}</option>`).join('');if(groupNames().includes(keep))gs.value=keep;renderMembers()}
function renderMembers(){const g=$('groupSelect').value,m=$('memberSelect'),members=swingGroups[g]||[];m.innerHTML=members.length?members.map(x=>`<option value="${x}">${x}${symbolNames[x]?' '+symbolNames[x]:''}</option>`).join(''):'<option value="">—</option>';const cur=$('symbol').value.trim().toUpperCase();if(members.includes(cur))m.value=cur;else if(members.length)m.value=members[0]}
function selectMember(symbol){if(!symbol)return;$('symbol').value=symbol;savePrefs();load()}
function cycleMember(delta){const g=$('groupSelect').value,a=swingGroups[g]||[];if(!a.length)return;let i=a.indexOf($('symbol').value.trim().toUpperCase());if(i<0)i=0;else i=(i+delta+a.length)%a.length;$('memberSelect').value=a[i];selectMember(a[i])}
function cycleGroup(delta){const a=groupNames();if(!a.length)return;let i=a.indexOf($('groupSelect').value);i=i<0?0:(i+delta+a.length)%a.length;$('groupSelect').value=a[i];renderMembers();const members=swingGroups[a[i]]||[];if(members.length)selectMember(members[0]);savePrefs()}
function renderGroupEditor(){const e=$('editGroup'),keep=e.value||$('groupSelect').value;e.innerHTML=groupNames().map(x=>`<option value="${x.replaceAll('&','&amp;').replaceAll('"','&quot;')}">${x}</option>`).join('');if(groupNames().includes(keep))e.value=keep;const a=swingGroups[e.value]||[];$('memberList').innerHTML=a.length?a.map(x=>`<div class="member-row"><span>${x}${symbolNames[x]?' '+symbolNames[x]:''}</span><button type="button" data-remove="${x}">移除</button></div>`).join(''):'<div class="empty">此群組尚無個股</div>'}
$('prevGroup').onclick=()=>cycleGroup(-1);$('nextGroup').onclick=()=>cycleGroup(1);$('prevMember').onclick=()=>cycleMember(-1);$('nextMember').onclick=()=>cycleMember(1);$('groupSelect').onchange=()=>{renderMembers();const a=swingGroups[$('groupSelect').value]||[];if(a.length)selectMember(a[0]);savePrefs()};$('memberSelect').onchange=()=>selectMember($('memberSelect').value);
const closeGroupModal=()=>{$('groupModal').classList.remove('open')};$('manageGroups').onclick=()=>{$('groupModal').classList.add('open');renderGroupEditor();history.pushState({a18GroupModal:true},'')};$('closeGroups').onclick=()=>{closeGroupModal();if(history.state?.a18GroupModal)history.back()};$('groupModal').addEventListener('click',e=>{if(e.target===$('groupModal')){closeGroupModal();if(history.state?.a18GroupModal)history.back()}});window.addEventListener('popstate',()=>{if($('groupModal').classList.contains('open'))closeGroupModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('groupModal').classList.contains('open')){closeGroupModal();if(history.state?.a18GroupModal)history.back()}});$('editGroup').onchange=renderGroupEditor;
$('addGroup').onclick=async()=>{const n=$('newGroupName').value.trim();if(!n||swingGroups[n])return;swingGroups[n]=[];$('newGroupName').value='';await saveGroups();$('editGroup').value=n;renderGroupEditor()};$('deleteGroup').onclick=async()=>{const g=$('editGroup').value;if(!g||!confirm(`刪除群組「${g}」？`))return;delete swingGroups[g];await saveGroups()};$('addMember').onclick=async()=>{const g=$('editGroup').value,sym=$('newMemberSymbol').value.trim().toUpperCase();if(!g||!sym)return;swingGroups[g]=[...new Set([...(swingGroups[g]||[]),sym])];$('newMemberSymbol').value='';await saveGroups()};$('memberList').onclick=async e=>{const sym=e.target?.dataset?.remove,g=$('editGroup').value;if(!sym||!g)return;swingGroups[g]=(swingGroups[g]||[]).filter(x=>x!==sym);await saveGroups()};
let prefs={};let saveStateTimer=null;function currentPrefs(){return{symbol:$('symbol').value.trim().toUpperCase(),interval:$('interval').value,date:$('date').value,overlay:$('overlay').checked,multiDay:$('multiDay').checked,lookbackDays:Math.max(1,Math.min(20,+$('lookbackDays').value||1)),group:$('groupSelect')?.value||'',showSectionNumbers:$('showSectionNumbers').checked,autoStrategyA:$('autoStrategyA').checked,autoStrategyB:$('autoStrategyB').checked,autoAStopPct:Math.max(0,+$('autoAStopPct').value||0),autoATrailPct:Math.max(0,+$('autoATrailPct').value||0),autoBStopPct:Math.max(0,+$('autoBStopPct').value||0),autoBTrailPct:Math.max(0,+$('autoBTrailPct').value||0)}}function savePrefs(){prefs=currentPrefs();clearTimeout(saveStateTimer);saveStateTimer=setTimeout(()=>fetch('/api/swing/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(prefs)}).catch(()=>{}),120)}
const dayNames=['週日','週一','週二','週三','週四','週五','週六'];function updateWeekday(){const v=$('date').value;if(!v){$('weekday').textContent='—';return}const d=new Date(v+'T12:00:00');$('weekday').textContent=dayNames[d.getDay()]}
async function shiftDay(delta){const v=$('date').value;if(!v)return;let d=new Date(v+'T12:00:00');for(let n=0;n<20;n++){d.setDate(d.getDate()+delta);const candidate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const now=new Date(),todayNav=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;if(delta>0&&candidate>todayNav)return;if(d.getDay()===0||d.getDay()===6)continue;try{const r=await fetch(`/api/calendar/non-trading/${candidate}`,{cache:'no-store'});if(r.ok&&(await r.json()).nonTrading)continue}catch{}$('date').value=candidate;updateWeekday();savePrefs();load();return}}
$('prevDay').addEventListener('click',()=>shiftDay(-1));$('nextDay').addEventListener('click',()=>shiftDay(1));$('symbol').addEventListener('change',savePrefs);$('interval').addEventListener('change',savePrefs);$('overlay').addEventListener('change',()=>{savePrefs();load()});$('multiDay').addEventListener('change',()=>{savePrefs();load()});$('lookbackDays').addEventListener('change',()=>{savePrefs();if($('multiDay').checked)load()});$('showSectionNumbers').addEventListener('change',()=>{document.body.classList.toggle('hide-section-numbers',!$('showSectionNumbers').checked);savePrefs()});
const n=new Date();const today=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;async function init(){try{const r=await fetch('/api/swing/state',{cache:'no-store'});if(r.ok)prefs=await r.json()}catch{}if(prefs.symbol)$('symbol').value=prefs.symbol;if(['1','5','60','300'].includes(String(prefs.interval)))$('interval').value=String(prefs.interval);else $('interval').value='5';$('overlay').checked=Boolean(prefs.overlay);$('multiDay').checked=Boolean(prefs.multiDay);$('autoStrategyA').checked=Boolean(prefs.autoStrategyA);$('autoStrategyB').checked=Boolean(prefs.autoStrategyB);$('autoAStopPct').value=Number.isFinite(+prefs.autoAStopPct)?+prefs.autoAStopPct:1;$('autoATrailPct').value=Number.isFinite(+prefs.autoATrailPct)?+prefs.autoATrailPct:.5;$('autoBStopPct').value=Number.isFinite(+prefs.autoBStopPct)?+prefs.autoBStopPct:.7;$('autoBTrailPct').value=Number.isFinite(+prefs.autoBTrailPct)?+prefs.autoBTrailPct:1;$('showSectionNumbers').checked=prefs.showSectionNumbers!==false;document.body.classList.toggle('hide-section-numbers',!$('showSectionNumbers').checked);if(prefs.lookbackDays)$('lookbackDays').value=Math.max(1,Math.min(20,+prefs.lookbackDays||1));$('date').value=/^\d{4}-\d{2}-\d{2}$/.test(String(prefs.date||''))?prefs.date:today;const q=new URLSearchParams(location.search),qs=q.get('symbol'),qd=q.get('date'),qi=q.get('interval');if(qs)$('symbol').value=qs.trim().toUpperCase();if(qd&&/^\d{4}-\d{2}-\d{2}$/.test(qd))$('date').value=qd;if(qi&&['1','5','60','300'].includes(qi))$('interval').value=qi;updateWeekday();await loadGroups();if(prefs.group&&groupNames().includes(prefs.group)){$('groupSelect').value=prefs.group;renderMembers()}state.timer=setInterval(load,5000);load()}init();})();
</script>
